{% assign wedding_display_title = product.title
  | remove: "Wedding Planner -"
  | remove: "Wedding Planner"
  | remove: "–"
  | remove: "—"
  | remove: "-"
  | strip
%}

<style>
  .tjs-wedding-title-wrap {
    margin: 6px 0 10px;
    font-family: inherit;
  }

  .tjs-wedding-title {
    margin: 0;
    max-width: 580px;
    font-size: clamp(28px, 3.2vw, 44px);
    line-height: 1.06;
    letter-spacing: -1.2px;
    color: #171717;
    font-weight: 800;
  }

  .tjs-wedding-title span {
    position: relative;
    display: inline;
    color: currentColor;
  }

  .tjs-wedding-title span::after {
    content: "";
    position: absolute;
    left: 0;
    bottom: 3px;
    width: 100%;
    height: 8px;
    border-radius: 999px;
    background: rgba(23,23,23, 0.65);
    z-index: -1;
  }

  .tjs-wedding-title-mini {
    margin-top: 9px;
    display: flex;
    align-items: center;
    gap: 7px;
    flex-wrap: wrap;
    color: #656565;
    font-size: 13px;
    line-height: 1.4;
    font-weight: 500;
  }

  .tjs-wedding-title-mini strong {
    color: #171717;
    font-weight: 700;
  }

  .tjs-wedding-title-dot {
    width: 4px;
    height: 4px;
    border-radius: 50%;
    background: #F5F5F3;
  }

  @media screen and (max-width: 749px) {
    .tjs-wedding-title-wrap {
      margin: 6px 0 10px;
      text-align: center;
    }

    .tjs-wedding-title {
      max-width: 100%;
      font-size: 29px;
      line-height: 1.08;
      letter-spacing: -0.9px;
    }

    .tjs-wedding-title span::after {
      bottom: 2px;
      height: 7px;
    }

    .tjs-wedding-title-mini {
      justify-content: center;
      margin: 10px auto 0;
      font-size: 12px;
      max-width: 94%;
      gap: 6px;
    }
  }
</style>

<div class="tjs-wedding-title-wrap">
  <h1 class="tjs-wedding-title">
    <span>{{ wedding_display_title }}</span>
  </h1>

  <div class="tjs-wedding-title-mini">
    <strong>124 Sides</strong>
    <span class="tjs-wedding-title-dot"></span>
    <strong>Hardbound Wiro</strong>
    <span class="tjs-wedding-title-dot"></span>
    <strong>Sticker Sheets Included</strong>
  </div>
</div>

{% assign current_variant = product.selected_or_first_available_variant %}
{% assign selling_price = current_variant.price %}
{% assign compare_price = current_variant.compare_at_price | default: 0 %}
{% assign total_save = 0 %}
{% assign final_discount_percent = 0 %}

{% if compare_price > selling_price %}
  {% assign total_save = compare_price | minus: selling_price %}
  {% assign final_discount_percent = total_save | times: 100 | divided_by: compare_price | round %}
{% endif %}

<style>
  .tjs-price-reveal {
    margin: 10px 0 16px;
    font-family: inherit;
  }

  .tjs-price-reveal * {
    box-sizing: border-box;
  }

  .tjs-price-reveal__row {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
  }

  .tjs-price-reveal__price {
    position: relative;
    display: inline-flex;
    align-items: center;
    color: #171717;
    font-size: 38px;
    line-height: 1;
    font-weight: 950;
    letter-spacing: -1.3px;
    white-space: nowrap;
    font-variant-numeric: tabular-nums;
    transition: transform 0.28s ease, color 0.28s ease;
  }

  .tjs-price-reveal.is-counting .tjs-price-reveal__price {
    color: currentColor;
    transform: translateY(-1px);
  }

  .tjs-price-reveal.is-final .tjs-price-reveal__price {
    color: #171717;
  }

  .tjs-price-reveal__price::after {
    content: "";
    position: absolute;
    left: -5px;
    right: -5px;
    bottom: -4px;
    height: 8px;
    border-radius: 999px;
    background: rgba(23,23,23, 0.14);
    z-index: -1;
    transform: scaleX(0);
    transform-origin: left;
    transition: transform 0.45s ease;
  }

  .tjs-price-reveal.is-counting .tjs-price-reveal__price::after,
  .tjs-price-reveal.is-final .tjs-price-reveal__price::after {
    transform: scaleX(1);
  }

  .tjs-price-reveal__compare {
    position: relative;
    color: #656565;
    font-size: 15px;
    line-height: 1;
    font-weight: 750;
    white-space: nowrap;
  }

  .tjs-price-reveal__compare::after {
    content: "";
    position: absolute;
    left: -2px;
    right: -2px;
    top: 50%;
    height: 2px;
    border-radius: 99px;
    background: #F5F5F3;
    transform: rotate(-6deg);
  }

  .tjs-price-reveal__badge {
    position: relative;
    display: inline-flex;
    align-items: center;
    gap: 5px;
    height: 27px;
    padding: 0 11px;
    border-radius: 999px;
    background: linear-gradient(135deg, #F5F5F3, #171717);
    color: #FFFFFF;
    font-size: 11px;
    line-height: 1;
    font-weight: 900;
    white-space: nowrap;
    overflow: hidden;
    box-shadow: 0 7px 16px rgba(47, 36, 32, 0.16);
    transition: background 0.35s ease, transform 0.35s ease;
  }

  .tjs-price-reveal__badge::before {
    content: "✦";
    color: currentColor;
    font-size: 10px;
  }

  .tjs-price-reveal__badge::after {
    content: "";
    position: absolute;
    top: -80%;
    left: -60%;
    width: 30px;
    height: 260%;
    background: linear-gradient(110deg, transparent, rgba(255,255,255,0.46), transparent);
    transform: rotate(18deg);
    animation: tjsPriceRevealShine 4.5s ease-in-out infinite;
  }

  .tjs-price-reveal.is-final .tjs-price-reveal__badge {
    background: linear-gradient(135deg, #171717, #F5F5F3);
    transform: scale(1.03);
  }

  @keyframes tjsPriceRevealShine {
    0%, 50% {
      left: -60%;
      opacity: 0;
    }
    62% {
      opacity: 1;
    }
    84%, 100% {
      left: 130%;
      opacity: 0;
    }
  }

  .tjs-price-reveal__line {
    margin-top: 8px;
    display: flex;
    align-items: center;
    gap: 7px;
    flex-wrap: wrap;
    color: #171717;
    font-size: 12.5px;
    line-height: 1.35;
    font-weight: 650;
  }

  .tjs-price-reveal__cart-btn {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 5px 11px;
    border-radius: 999px;
    border: 0;
    background: #F56A28;
    color: #171717;
    text-decoration: none;
    font-size: 10px;
    line-height: 1;
    font-weight: 900;
    letter-spacing: 0.35px;
    text-transform: uppercase;
    white-space: nowrap;
    overflow: hidden;
    cursor: pointer;
    font-family: inherit;
  }

  .tjs-price-reveal__cart-btn::after {
    content: "";
    position: absolute;
    top: -80%;
    left: -70%;
    width: 22px;
    height: 260%;
    background: linear-gradient(110deg, transparent, rgba(255,255,255,0.42), transparent);
    transform: rotate(18deg);
    animation: tjsPriceRevealCtaShine 4.2s ease-in-out infinite;
  }

  .tjs-price-reveal__cart-btn.is-loading {
    opacity: 0.72;
    pointer-events: none;
  }

  @keyframes tjsPriceRevealCtaShine {
    0%, 50% {
      left: -70%;
      opacity: 0;
    }
    62% {
      opacity: 1;
    }
    84%, 100% {
      left: 130%;
      opacity: 0;
    }
  }

  .tjs-price-reveal[data-has-discount="false"] .tjs-price-reveal__compare,
  .tjs-price-reveal[data-has-discount="false"] .tjs-price-reveal__badge {
    display: none !important;
  }

  @media screen and (max-width: 749px) {
    .tjs-price-reveal {
      margin: 9px 0 14px;
    }

    .tjs-price-reveal__row {
      gap: 7px;
    }

    .tjs-price-reveal__price {
      font-size: 34px;
      letter-spacing: -1.1px;
    }

    .tjs-price-reveal__compare {
      font-size: 14px;
    }

    .tjs-price-reveal__badge {
      height: 26px;
      font-size: 10px;
      padding: 0 10px;
    }

    .tjs-price-reveal__line {
      font-size: 11.7px;
      gap: 5px;
      margin-top: 6px;
    }

    .tjs-price-reveal__cart-btn {
      padding: 5px 9px;
      font-size: 9.5px;
    }
  }
</style>

<div
  class="tjs-price-reveal"
  data-tjs-price-reveal
  data-has-discount="{% if compare_price > selling_price %}true{% else %}false{% endif %}"
>
  <div class="tjs-price-reveal__row">
    <div class="tjs-price-reveal__price" data-tjs-reveal-price>
      ₹{{ selling_price | money_without_currency | remove: '.00' | strip }}
    </div>

    <div class="tjs-price-reveal__compare" data-tjs-reveal-compare>
      {% if compare_price > selling_price %}
        ₹{{ compare_price | money_without_currency | remove: '.00' | strip }}
      {% endif %}
    </div>

    <div class="tjs-price-reveal__badge" data-tjs-reveal-badge>
      {% if compare_price > selling_price %}
        {{ final_discount_percent }}% Off
      {% endif %}
    </div>
  </div>


</div>

<script type="application/json" data-tjs-price-reveal-variants>
  {
    {% for variant in product.variants %}
      "{{ variant.id }}": {
        "price": {{ variant.price | json }},
        "compare_at_price": {{ variant.compare_at_price | default: 0 | json }}
      }{% unless forloop.last %},{% endunless %}
    {% endfor %}
  }
</script>

<script>
  (function () {
    function formatINRFromCents(cents) {
      var amount = Math.round(Number(cents || 0) / 100);

      try {
        return "₹" + amount.toLocaleString("en-IN", {
          maximumFractionDigits: 0
        });
      } catch (e) {
        return "₹" + amount;
      }
    }

    function animateNumber(el, fromCents, toCents, duration) {
      var start = Math.round(Number(fromCents || 0) / 100);
      var end = Math.round(Number(toCents || 0) / 100);
      var startTime = null;

      function easeOutCubic(t) {
        return 1 - Math.pow(1 - t, 3);
      }

      function frame(timestamp) {
        if (!startTime) startTime = timestamp;

        var progress = Math.min((timestamp - startTime) / duration, 1);
        var eased = easeOutCubic(progress);
        var current = Math.round(start + (end - start) * eased);

        try {
          el.textContent = "₹" + current.toLocaleString("en-IN", {
            maximumFractionDigits: 0
          });
        } catch (e) {
          el.textContent = "₹" + current;
        }

        if (progress < 1) {
          requestAnimationFrame(frame);
        }
      }

      requestAnimationFrame(frame);
    }

    function initTjsPriceReveal() {
      var box = document.querySelector("[data-tjs-price-reveal]");
      var priceEl = document.querySelector("[data-tjs-reveal-price]");
      var compareEl = document.querySelector("[data-tjs-reveal-compare]");
      var badgeEl = document.querySelector("[data-tjs-reveal-badge]");
      var addButton = document.querySelector("[data-tjs-reveal-add]");
      var jsonEl = document.querySelector("[data-tjs-price-reveal-variants]");

      if (!box || !priceEl || !compareEl || !badgeEl || !jsonEl) return;

      var variants = {};

      try {
        variants = JSON.parse(jsonEl.textContent);
      } catch (e) {
        return;
      }

      function getVariantId() {
        var idInput = document.querySelector('form[action*="/cart/add"] [name="id"]');
        return idInput ? idInput.value : null;
      }

      function updatePrice(variantId) {
        var variant = variants[String(variantId)];
        if (!variant) return;

        var price = Number(variant.price || 0);
        var compare = Number(variant.compare_at_price || 0);
        var hasDiscount = compare > price;
        var finalPercent = hasDiscount ? Math.round(((compare - price) * 100) / compare) : 0;

        box.classList.remove("is-counting", "is-final");

        if (!hasDiscount) {
          priceEl.textContent = formatINRFromCents(price);
          compareEl.textContent = "";
          badgeEl.textContent = "";
          box.setAttribute("data-has-discount", "false");
          return;
        }

        box.setAttribute("data-has-discount", "true");

        priceEl.textContent = formatINRFromCents(compare);
        compareEl.textContent = formatINRFromCents(compare);
        badgeEl.textContent = "Price Drop";

        setTimeout(function () {
          box.classList.add("is-counting");
          animateNumber(priceEl, compare, price, 1100);
        }, 550);

        setTimeout(function () {
          box.classList.remove("is-counting");
          box.classList.add("is-final");
          priceEl.textContent = formatINRFromCents(price);
          badgeEl.textContent = finalPercent + "% Off";
        }, 1750);
      }

      if (addButton && !addButton.dataset.tjsClickReady) {
        addButton.dataset.tjsClickReady = "true";

        addButton.addEventListener("click", function () {
          var realAddButton =
            document.querySelector('form[action*="/cart/add"] button[type="submit"]:not([disabled])') ||
            document.querySelector('form[action*="/cart/add"] [name="add"]:not([disabled])') ||
            document.querySelector('.product-form__submit:not([disabled])') ||
            document.querySelector('.product-form button[type="submit"]:not([disabled])') ||
            document.querySelector('[data-add-to-cart]:not([disabled])');

          if (realAddButton && typeof realAddButton.click === "function") {
            addButton.classList.add("is-loading");
            addButton.textContent = "Adding...";
            realAddButton.click();

            setTimeout(function () {
              addButton.textContent = "Add To Cart →";
              addButton.classList.remove("is-loading");
            }, 1400);
          } else {
            addButton.textContent = "Select Option";

            setTimeout(function () {
              addButton.textContent = "Add To Cart →";
            }, 1400);
          }
        });
      }

      document.addEventListener("change", function (event) {
        if (
          event.target.matches('[name="id"]') ||
          event.target.matches('input[type="radio"]') ||
          event.target.matches("select")
        ) {
          setTimeout(function () {
            var variantId = getVariantId();
            if (variantId) updatePrice(variantId);
          }, 100);
        }
      });

      document.addEventListener("variant:change", function (event) {
        if (event.detail && event.detail.variant && event.detail.variant.id) {
          updatePrice(event.detail.variant.id);
        }
      });

      var initialVariantId = getVariantId() || "{{ current_variant.id }}";

      if (initialVariantId) {
        updatePrice(initialVariantId);
      }
    }

    document.addEventListener("DOMContentLoaded", initTjsPriceReveal);
    document.addEventListener("shopify:section:load", initTjsPriceReveal);
  })();
</script>

{% assign planner_collection = collections['wedding-planners'] %}

{% assign selected_style_title = product.title
  | remove: "Wedding Planner -"
  | remove: "Wedding Planner"
  | remove: "Undated Yearly Planner 2025 Collection"
  | remove: "Undated Yearly Planner Current State"
  | remove: "Undated Yearly Planner"
  | remove: "Undated Yealry Planner"
  | remove: "Limited Edition Undated Planner"
  | remove: "(Limited Hardbound Collection)"
  | remove: "Limited Hardbound Collection"
  | remove: "Ultimate Sticker Book"
  | remove: "+"
  | remove: "–"
  | remove: "—"
  | remove: "-"
  | strip
%}

<style>
  .tjs-cover-selector {
    margin: 16px 0 18px;
    font-family: inherit;
  }

  .tjs-cover-selector__head {
    margin-bottom: 10px;
  }

  .tjs-cover-selector__label {
    font-size: 11px;
    line-height: 1;
    letter-spacing: 1.1px;
    text-transform: uppercase;
    color: currentColor;
    font-weight: 800;
    margin-bottom: 6px;
  }

  .tjs-cover-selector__selected {
    font-size: 13px;
    line-height: 1.35;
    color: #171717;
    font-weight: 500;
  }

  .tjs-cover-selector__selected strong {
    color: #171717;
    font-weight: 800;
  }

  .tjs-cover-selector__grid {
    display: flex;
    gap: 10px;
    overflow-x: auto;
    padding: 2px 2px 6px;
    scrollbar-width: none;
    -webkit-overflow-scrolling: touch;
  }

  .tjs-cover-selector__grid::-webkit-scrollbar {
    display: none;
  }

  .tjs-cover-option {
    position: relative;
    flex: 0 0 74px;
    width: 74px;
    text-decoration: none;
    color: inherit;
  }

  .tjs-cover-option__image-wrap {
    position: relative;
    aspect-ratio: 1 / 1.28;
    border-radius: 13px;
    overflow: hidden;
    background: #FFFFFF;
    border: 1px solid rgba(23,23,23, 0.38);
    box-shadow: 0 8px 18px rgba(47, 36, 32, 0.07);
    transition: transform 0.25s ease, border-color 0.25s ease, box-shadow 0.25s ease;
  }

  .tjs-cover-option:hover .tjs-cover-option__image-wrap {
    transform: translateY(-2px);
    border-color: rgba(23,23,23, 0.55);
    box-shadow: 0 12px 24px rgba(47, 36, 32, 0.12);
  }

  .tjs-cover-option__image {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
  }

  .tjs-cover-option__fallback {
    width: 100%;
    height: 100%;
    display: grid;
    place-items: center;
    padding: 8px;
    text-align: center;
    font-size: 10px;
    line-height: 1.25;
    color: currentColor;
    font-weight: 700;
  }

  .tjs-cover-option__title {
    margin-top: 6px;
    font-size: 10.5px;
    line-height: 1.25;
    color: #656565;
    font-weight: 700;
    text-align: center;
    letter-spacing: 0.1px;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
  }

  .tjs-cover-option.is-active .tjs-cover-option__image-wrap {
    border: 2px solid #DADADA;
    box-shadow:
      0 0 0 3px rgba(23,23,23, 0.22),
      0 12px 24px rgba(47, 36, 32, 0.12);
  }

  .tjs-cover-option.is-active::after {
    content: "Selected";
    position: absolute;
    top: 6px;
    left: 50%;
    transform: translateX(-50%);
    z-index: 2;
    padding: 4px 7px;
    border-radius: 999px;
    background: rgba(47, 36, 32, 0.88);
    color: #FFFFFF;
    font-size: 8.5px;
    line-height: 1;
    font-weight: 800;
    letter-spacing: 0.2px;
    pointer-events: none;
  }

  .tjs-cover-option.is-active .tjs-cover-option__title {
    color: #171717;
    font-weight: 850;
  }

  @media screen and (max-width: 749px) {
    .tjs-cover-selector {
      margin: 15px 0 17px;
      text-align: center;
    }

    .tjs-cover-selector__label {
      font-size: 10px;
    }

    .tjs-cover-selector__selected {
      font-size: 12.5px;
    }

    .tjs-cover-selector__grid {
      justify-content: flex-start;
      gap: 9px;
      padding-left: 2px;
      padding-right: 2px;
    }

    .tjs-cover-option {
      flex-basis: 68px;
      width: 68px;
    }

    .tjs-cover-option__image-wrap {
      border-radius: 12px;
    }

    .tjs-cover-option__title {
      font-size: 10px;
    }
  }
</style>

{% if planner_collection != blank and planner_collection.products_count > 0 %}
  <div class="tjs-cover-selector">
    <div class="tjs-cover-selector__head">
      <div class="tjs-cover-selector__label">
        Choose Your Cover, To Match Your Vibe
      </div>

      <div class="tjs-cover-selector__selected">
        Selected: <strong>{{ selected_style_title }}</strong>
      </div>
    </div>

    <div class="tjs-cover-selector__grid">
      {% for linked_product in planner_collection.products %}
        {% assign style_title = linked_product.title
          | remove: "Wedding Planner -"
          | remove: "Wedding Planner"
          | remove: "Undated Yearly Planner 2025 Collection"
          | remove: "Undated Yearly Planner Current State"
          | remove: "Undated Yearly Planner"
          | remove: "Undated Yealry Planner"
          | remove: "Limited Edition Undated Planner"
          | remove: "(Limited Hardbound Collection)"
          | remove: "Limited Hardbound Collection"
          | remove: "Ultimate Sticker Book"
          | remove: "+"
          | remove: "–"
          | remove: "—"
          | remove: "-"
          | strip
        %}

        <a
          href="{{ linked_product.url }}"
          class="tjs-cover-option {% if linked_product.handle == product.handle %}is-active{% endif %}"
          aria-label="Select {{ style_title | escape }}"
        >
          <div class="tjs-cover-option__image-wrap">
            {% if linked_product.featured_image %}
              <img
                class="tjs-cover-option__image"
                src="{{ linked_product.featured_image | image_url: width: 220 }}"
                alt="{{ style_title | escape }}"
                loading="lazy"
              >
            {% else %}
              <div class="tjs-cover-option__fallback">
                {{ style_title }}
              </div>
            {% endif %}
          </div>

          <div class="tjs-cover-option__title">
            {{ style_title }}
          </div>
        </a>
      {% endfor %}
    </div>
  </div>
{% endif %}

settings.custom_liquid:
{% assign wedding_sticker_image_url = "https://thejuneshop.com/cdn/shop/files/zUnDatedStickerbook_ab559cc7-53d1-4a0e-bd1a-17e04575d710.gif?v=1697707538&width=990" %}

<style>
  .tjs-wedding-sticker-section {
    position: relative;
    margin: 40px 0;
    padding: 44px 18px;
    font-family: inherit;
    overflow: hidden;
    border-radius: 34px;
    background:
      radial-gradient(circle at 12% 16%, rgba(23,23,23, 0.48), transparent 27%),
      radial-gradient(circle at 86% 20%, rgba(23,23,23, 0.48), transparent 30%),
      radial-gradient(circle at 50% 100%, rgba(23,23,23, 0.42), transparent 34%),
      linear-gradient(135deg, #FFFFFF 0%, #FFFFFF 48%, #FFFFFF 100%);
    border: 1px solid rgba(23,23,23, 0.32);
  }

  .tjs-wedding-sticker-section::before {
    content: "";
    position: absolute;
    inset: -40%;
    background:
      radial-gradient(circle, rgba(255,255,255,0.56) 0 1px, transparent 2px) 0 0 / 36px 36px,
      linear-gradient(115deg, transparent 0%, rgba(255,255,255,0.35) 48%, transparent 60%);
    animation: tjsWeddingStickerBgDrift 16s linear infinite;
    pointer-events: none;
  }

