{% if planner_collection != blank and planner_collection.products_count > 0 %}
  <section class="tjs-cover-gallery-section">
    <div class="tjs-cover-gallery-container">
      <div class="tjs-cover-gallery-head">
        <div class="tjs-cover-gallery-kicker">
          Explore The Collection
        </div>

        <h2 class="tjs-cover-gallery-title">
          Choose the cover that feels <span>most like you</span>
        </h2>

        <div class="tjs-cover-gallery-subtitle">
          Every cover has its own personality. Swipe through the planner gallery and find the design that matches your next chapter.
        </div>
      </div>

      <div class="tjs-cover-gallery-frame">
        <div class="tjs-cover-gallery-track">
          {% for linked_product in planner_collection.products limit: 12 %}
            {% assign style_title = linked_product.title
              | remove: "Undated Yearly Planner 2025 Collection"
              | remove: "Undated Yearly Planner Current State"
              | remove: "Undated Yearly Planner"
              | remove: "Undated Yealry Planner"
              | remove: "Limited Edition Undated Planner"
              | remove: "(Limited Hardbound Collection)"
              | remove: "Limited Hardbound Collection"
              | remove: "Ultimate Sticker Book"
              | remove: "+"
              | remove: "–"
              | remove: "—"
              | remove: "-"
              | strip
            %}

            <a class="tjs-cover-gallery-card" href="{{ linked_product.url }}">
              <div class="tjs-cover-gallery-cover">
                {% if linked_product.handle == product.handle %}
                  <div class="tjs-cover-gallery-badge">Viewing Now</div>
                {% endif %}

                {% if linked_product.featured_image %}
                  <img
                    class="tjs-cover-gallery-image"
                    src="{{ linked_product.featured_image | image_url: width: 900 }}"
                    alt="{{ style_title | escape }}"
                    loading="lazy"
                  >
                {% else %}
                  <div class="tjs-cover-gallery-empty">
                    {{ style_title }}
                  </div>
                {% endif %}

                <div class="tjs-cover-gallery-info">
                  <div class="tjs-cover-gallery-product-title">
                    {{ style_title }}
                  </div>

                  <div class="tjs-cover-gallery-product-meta">
                    <div class="tjs-cover-gallery-price">
                      {{ linked_product.price | money }}
                    </div>
                    <div class="tjs-cover-gallery-view">
                      View
                    </div>
                  </div>
                </div>
              </div>
            </a>
          {% endfor %}
        </div>

        <div class="tjs-cover-gallery-foot">
          <div class="tjs-cover-gallery-note">
            Explore more planner covers from this collection
          </div>

          <a class="tjs-cover-gallery-button" href="{{ planner_collection.url }}">
            View Full Collection
          </a>
        </div>
      </div>
    </div>
  </section>
{% endif %}
